        emit(rows, args.output, columns)
        return 0
    except UserError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    except (OSError, ValueError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
# CSV Insights

Dependency-free CSV filtering and grouping for Python 3.11+.

```text
python3 main.py INPUT.csv [--where COLUMN=VALUE ...] [--group-by COLUMN] [--sum COLUMN] [--avg COLUMN] [--output json|csv]
```

Without aggregation, matching rows are emitted in input order. `--sum` and
`--avg` require `--group-by`; grouped results are sorted by group value.
Output defaults to compact JSON and can be selected as RFC-compliant CSV.
Numeric aggregation uses `decimal.Decimal`, and malformed CSV, headers,
filters, columns, and numeric cells produce a non-zero exit status with an
explanation on stderr.
